import React, { useState, useEffect } from 'react';
import { Wine, Music, Users, Clock, CheckCircle, Calendar, Calculator, TrendingDown, Ticket, Briefcase, PartyPopper, AlertTriangle, Beer, Martini, Info, Sparkles } from 'lucide-react';
import { SEO } from '../components/SEO';
import { useLanguage } from '../context/LanguageContext';

interface PrivateFormData {
  name: string;
  email: string;
  date: string;
  duration: number;
  guests: number;
  ticketsPerGuest: number;
}

interface PromoterFormData {
  collectiveName: string;
  contactName: string;
  email: string;
  socialLink: string;
  concept: string;
  expectedTurnout: number;
}

export const PrivateEvents: React.FC = () => {
  const { t } = useLanguage();
  const [activeTab, setActiveTab] = useState<'private' | 'promoter'>('private');
  const [isSubmitted, setIsSubmitted] = useState(false);

  // Private Event State
  const [privateForm, setPrivateForm] = useState<PrivateFormData>({
    name: '',
    email: '',
    date: new Date().toISOString().split('T')[0],
    duration: 4,
    guests: 40,
    ticketsPerGuest: 2 // Default 2 tickets per person
  });

  // Promoter Event State
  const [promoterForm, setPromoterForm] = useState<PromoterFormData>({
    collectiveName: '',
    contactName: '',
    email: '',
    socialLink: '',
    concept: '',
    expectedTurnout: 100
  });

  // Quote State
  const [quote, setQuote] = useState({
    rentalCost: 0,
    consumableRevenue: 0,
    discount: 0,
    finalTotal: 0,
    pricePerPerson: 0,
    totalDrinks: 0,
    isWeekend: false,
    timeWarning: false
  });

  // Handle Input Changes
  const handlePrivateChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setPrivateForm(prev => ({
      ...prev,
      [name]: ['guests', 'duration', 'ticketsPerGuest'].includes(name) ? Number(value) : value
    }));
  };

  const handlePromoterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setPromoterForm(prev => ({ ...prev, [name]: value }));
  };

  // Calculate Logic
  useEffect(() => {
    const calculateQuote = () => {
      const WEEKEND_RATE = 100;
      const WEEKDAY_RATE = 60;
      const TICKET_PRICE = 10; // Euros per ticket

      // Date Logic
      let isWeekend = false;
      if (privateForm.date) {
        const day = new Date(privateForm.date).getDay();
        isWeekend = day === 5 || day === 6; // Fri or Sat
      }

      const hourlyRate = isWeekend ? WEEKEND_RATE : WEEKDAY_RATE;

      // Rental Base
      const baseRental = privateForm.duration * hourlyRate;

      // Ticket Logic
      const totalDrinks = privateForm.guests * privateForm.ticketsPerGuest;
      const totalConsumableRevenue = totalDrinks * TICKET_PRICE;

      // Hidden Formula: We credit 50% of the consumable spend towards the rental
      const calculatedDiscount = Math.min(baseRental, totalConsumableRevenue * 0.5);

      const finalTotal = Math.max(0, baseRental - calculatedDiscount) + totalConsumableRevenue;
      const pricePerPerson = finalTotal / privateForm.guests;

      setQuote({
        rentalCost: baseRental,
        consumableRevenue: totalConsumableRevenue,
        discount: calculatedDiscount,
        finalTotal: finalTotal, 
        pricePerPerson,
        totalDrinks,
        isWeekend,
        timeWarning: isWeekend 
      });
    };

    calculateQuote();
  }, [privateForm]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitted(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className="min-h-screen bg-mat-900 flex flex-col">
      <SEO titleKey="seo.private.title" descriptionKey="seo.private.description" />

      {/* Hero Section */}
      <div className="relative bg-mat-800 py-20 border-b border-mat-700 overflow-hidden">
        <div className="absolute inset-0 opacity-40">
             <img 
               src="https://images.unsplash.com/photo-1566737236500-c8ac43014a67?q=80&w=2000&auto=format&fit=crop" 
               alt="Club Crowd" 
               className="w-full h-full object-cover"
             />
             <div className="absolute inset-0 bg-mat-900/90"></div>
        </div>
        <div className="container mx-auto px-6 text-center relative z-10">
          <h1 className="text-5xl md:text-7xl font-black uppercase tracking-tighter text-white mb-6 drop-shadow-xl">
            {t('private.hero.title')}
          </h1>
          <p className="text-gray-300 max-w-2xl mx-auto text-xl font-light leading-relaxed">
            {t('private.hero.desc')}
          </p>
        </div>
      </div>

      <div className="container mx-auto px-6 py-12 max-w-6xl">

        {/* Tab Selector */}
        <div className="grid grid-cols-2 gap-4 mb-12 max-w-2xl mx-auto">
          <button 
            onClick={() => { setActiveTab('private'); setIsSubmitted(false); }}
            className={`p-6 border-2 transition-all duration-300 flex flex-col items-center gap-3 group ${
              activeTab === 'private' 
                ? 'border-mat-500 bg-mat-800 shadow-[0_0_30px_rgba(234,88,12,0.2)]' 
                : 'border-mat-800 bg-mat-900/50 opacity-60 hover:opacity-100 hover:border-mat-700'
            }`}
          >
            <PartyPopper className={`w-8 h-8 ${activeTab === 'private' ? 'text-mat-500' : 'text-gray-400'}`} />
            <div className="text-center">
              <span className={`block text-lg font-bold uppercase tracking-widest ${activeTab === 'private' ? 'text-white' : 'text-gray-400'}`}>{t('private.tab.private')}</span>
            </div>
          </button>

          <button 
            onClick={() => { setActiveTab('promoter'); setIsSubmitted(false); }}
            className={`p-6 border-2 transition-all duration-300 flex flex-col items-center gap-3 group ${
              activeTab === 'promoter' 
                ? 'border-mat-500 bg-mat-800 shadow-[0_0_30px_rgba(234,88,12,0.2)]' 
                : 'border-mat-800 bg-mat-900/50 opacity-60 hover:opacity-100 hover:border-mat-700'
            }`}
          >
            <Briefcase className={`w-8 h-8 ${activeTab === 'promoter' ? 'text-mat-500' : 'text-gray-400'}`} />
            <div className="text-center">
              <span className={`block text-lg font-bold uppercase tracking-widest ${activeTab === 'promoter' ? 'text-white' : 'text-gray-400'}`}>{t('private.tab.promoter')}</span>
            </div>
          </button>
        </div>

        {/* CONTENT AREA */}
        <div className="animate-fade-in">

          {isSubmitted ? (
             <div className="text-center py-16 bg-mat-800 border border-mat-700 shadow-2xl p-10 max-w-2xl mx-auto">
                <div className="w-24 h-24 bg-mat-900 rounded-full flex items-center justify-center mx-auto mb-6 border border-mat-500 shadow-xl">
                  <CheckCircle className="w-12 h-12 text-mat-500" />
                </div>
                <h3 className="text-3xl font-black text-white uppercase mb-4">{t('private.success.title')}</h3>
                <p className="text-gray-400 text-lg max-w-md mx-auto mb-8">
                  {activeTab === 'private' 
                    ? t('private.success.msg_private')
                    : t('private.success.msg_promoter')
                  }
                </p>
                <button 
                   onClick={() => setIsSubmitted(false)} 
                   className="text-mat-500 font-bold uppercase tracking-widest hover:text-white transition-colors underline underline-offset-4"
                >
                  {t('private.btn.another')}
                </button>
             </div>
          ) : (
            <>
              {/* ================= PRIVATE CELEBRATION FORM ================= */}
              {activeTab === 'private' && (
                <div className="grid lg:grid-cols-12 gap-8">

                   {/* LEFT COLUMN: SIMULATOR DASHBOARD */}
                   <div className="lg:col-span-8 bg-mat-900 border-2 border-mat-700 shadow-2xl relative overflow-hidden rounded-lg">
                      {/* Top Bar: Rate Type */}
                      <div className="bg-black/50 p-2 text-center border-b border-mat-800">
                         {quote.isWeekend ? (
                            <span className="text-amber-500 text-xs font-bold uppercase tracking-widest flex items-center justify-center gap-2">
                               <Sparkles className="w-3 h-3" /> {t('private.simulator.weekend')}
                            </span>
                         ) : (
                            <span className="text-gray-500 text-xs font-bold uppercase tracking-widest flex items-center justify-center gap-2">
                               <CheckCircle className="w-3 h-3" /> {t('private.simulator.weekday')}
                            </span>
                         )}
                      </div>

                      {/* MAIN OUTPUT DISPLAY (LCD STYLE) */}
                      <div className="p-8 md:p-12 text-center border-b border-mat-700 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-mat-800 to-mat-900">
                         <div className="inline-block mb-2">
                            <span className="text-mat-500 text-xs font-black uppercase tracking-[0.3em]">{t('private.simulator.est_total')}</span>
                         </div>
                         <div className="text-6xl md:text-9xl font-black text-white leading-none tracking-tighter mb-4 drop-shadow-[0_0_15px_rgba(255,255,255,0.1)] font-exo">
                            €{quote.finalTotal.toFixed(0)}
                         </div>
                         <div className="flex items-center justify-center gap-2 text-gray-400 text-sm font-mono bg-black/30 inline-block px-4 py-1 rounded-full border border-mat-800">
                            <span>{t('private.simulator.pp')}:</span>
                            <span className="text-mat-500 font-bold">€{quote.pricePerPerson.toFixed(0)}</span>
                         </div>
                      </div>

                      {/* INCLUDED GRID (3 COLUMNS) */}
                      <div className="grid grid-cols-3 divide-x divide-mat-700 bg-mat-800 border-b border-mat-700">
                         <div className="p-6 text-center group hover:bg-mat-700/50 transition-colors">
                            <div className="mb-2 flex justify-center"><Clock className="w-6 h-6 text-mat-500" /></div>
                            <div className="text-2xl font-black text-white mb-1">{privateForm.duration} H</div>
                            <div className="text-[10px] text-gray-400 uppercase tracking-widest font-bold">{t('private.simulator.hours_venue')}</div>
                         </div>
                         <div className="p-6 text-center group hover:bg-mat-700/50 transition-colors">
                            <div className="mb-2 flex justify-center"><Martini className="w-6 h-6 text-mat-500" /></div>
                            <div className="text-2xl font-black text-white mb-1">{quote.totalDrinks}</div>
                            <div className="text-[10px] text-gray-400 uppercase tracking-widest font-bold">{t('private.simulator.total_drinks')}</div>
                         </div>
                         <div className="p-6 text-center group hover:bg-mat-700/50 transition-colors">
                            <div className="mb-2 flex justify-center"><Users className="w-6 h-6 text-mat-500" /></div>
                            <div className="text-xl font-black text-white mb-1 uppercase tracking-tight">{t('private.simulator.includes')}</div>
                            <div className="text-[10px] text-gray-400 uppercase tracking-widest font-bold">{t('private.simulator.staff')}</div>
                         </div>
                      </div>

                      {/* CONTROLS AREA */}
                      <div className="p-8 space-y-10 bg-mat-900">
                         {/* Date Picker (Determines Rate) */}
                         <div>
                            <label className="flex justify-between text-xs font-bold text-mat-500 uppercase tracking-widest mb-3">
                               <span>{t('private.label.date')}</span>
                            </label>
                            <input 
                              type="date" 
                              name="date"
                              value={privateForm.date}
                              onChange={handlePrivateChange}
                              className="w-full bg-mat-800 border border-mat-700 text-white p-4 focus:border-mat-500 outline-none font-mono text-sm uppercase"
                            />
                         </div>

                         {/* Sliders Grid */}
                         <div className="grid md:grid-cols-2 gap-10">
                            {/* Guests Slider */}
                            <div className="space-y-4">
                               <div className="flex justify-between text-xs font-bold text-mat-500 uppercase tracking-widest">
                                  <span>{t('private.guest_count')}</span>
                                  <span className="text-white text-lg font-black">{privateForm.guests} {t('private.people')}</span>
                               </div>
                               <div className="relative pt-1">
                                  <input 
                                     type="range" 
                                     name="guests" 
                                     min="25" 
                                     max="100" 
                                     step="5"
                                     value={privateForm.guests}
                                     onChange={handlePrivateChange as any}
                                     className="w-full h-2 bg-mat-800 rounded-lg appearance-none cursor-pointer accent-mat-500 border border-mat-700"
                                  />
                                  <div className="flex justify-between text-[10px] text-gray-600 mt-2 font-mono">
                                     <span>25</span>
                                     <span>50</span>
                                     <span>75</span>
                                     <span>100</span>
                                  </div>
                               </div>
                            </div>

                            {/* Duration Slider */}
                            <div className="space-y-4">
                               <div className="flex justify-between text-xs font-bold text-mat-500 uppercase tracking-widest">
                                  <span>{t('private.label.duration')}</span>
                                  <span className="text-white text-lg font-black">{privateForm.duration} HORAS</span>
                               </div>
                               <div className="relative pt-1">
                                  <input 
                                     type="range" 
                                     name="duration" 
                                     min="3" 
                                     max="6" 
                                     step="1"
                                     value={privateForm.duration}
                                     onChange={handlePrivateChange as any}
                                     className="w-full h-2 bg-mat-800 rounded-lg appearance-none cursor-pointer accent-mat-500 border border-mat-700"
                                  />
                                  <div className="flex justify-between text-[10px] text-gray-600 mt-2 font-mono">
                                     <span>3H</span>
                                     <span>4H</span>
                                     <span>5H</span>
                                     <span>6H</span>
                                  </div>
                               </div>
                            </div>
                         </div>

                         {/* Drinks Buttons Selector */}
                         <div>
                            <div className="flex justify-between text-xs font-bold text-mat-500 uppercase tracking-widest mb-4">
                               <span>{t('private.tickets_per_guest')}</span>
                               <span className="text-white font-black">{privateForm.ticketsPerGuest} / pp</span>
                            </div>
                            <div className="grid grid-cols-5 gap-3">
                               {[0, 1, 2, 3, 4].map(qty => (
                                  <button
                                    key={qty}
                                    type="button"
                                    onClick={() => setPrivateForm(prev => ({ ...prev, ticketsPerGuest: qty }))}
                                    className={`py-5 text-lg font-black border transition-all duration-300 ${
                                       privateForm.ticketsPerGuest === qty 
                                       ? 'bg-mat-500 border-mat-500 text-white shadow-[0_0_20px_rgba(234,88,12,0.5)] scale-105 z-10' 
                                       : 'bg-mat-800 border-mat-700 text-gray-500 hover:border-mat-500 hover:text-white'
                                    }`}
                                  >
                                     {qty}
                                  </button>
                               ))}
                            </div>
                            <p className="text-center text-[10px] text-gray-500 mt-4 flex items-center justify-center gap-2">
                               <Info className="w-3 h-3" /> {t('private.ticket_info')}
                            </p>
                         </div>
                      </div>

                      {quote.timeWarning && (
                           <div className="bg-amber-900/40 p-4 text-center text-amber-500 text-xs font-bold uppercase tracking-widest border-t border-amber-900/50 flex items-center justify-center gap-3">
                              <AlertTriangle className="w-4 h-4" /> {t('private.weekend_warning')}
                           </div>
                       )}
                   </div>

                   {/* RIGHT COLUMN: BOOKING FORM */}
                   <div className="lg:col-span-4">
                      <div className="bg-mat-800 p-8 border-2 border-mat-700 shadow-xl rounded-lg h-fit sticky top-24">
                         <h3 className="text-xl font-black text-white uppercase tracking-wider mb-6 pb-4 border-b border-mat-700 flex items-center gap-3">
                           <PartyPopper className="w-5 h-5 text-mat-500" /> {t('private.booking_details')}
                         </h3>
                         <form onSubmit={handleSubmit} className="space-y-6">
                            <div>
                               <label className="block text-xs font-bold text-mat-500 uppercase mb-2">{t('private.label.name')}</label>
                               <input 
                                  required
                                  type="text" 
                                  name="name"
                                  value={privateForm.name}
                                  onChange={handlePrivateChange}
                                  className="w-full bg-mat-900 border border-mat-700 text-white p-4 focus:border-mat-500 outline-none transition-colors rounded-sm"
                                  placeholder="Full Name"
                               />
                            </div>
                            <div>
                               <label className="block text-xs font-bold text-mat-500 uppercase mb-2">{t('private.label.email')}</label>
                               <input 
                                  required
                                  type="email" 
                                  name="email"
                                  value={privateForm.email}
                                  onChange={handlePrivateChange}
                                  className="w-full bg-mat-900 border border-mat-700 text-white p-4 focus:border-mat-500 outline-none transition-colors rounded-sm"
                                  placeholder="email@example.com"
                               />
                            </div>

                            <button type="submit" className="w-full bg-mat-500 hover:bg-mat-400 text-white font-black py-6 uppercase tracking-widest transition-all shadow-xl hover:shadow-mat-500/30 hover:-translate-y-1 mt-4 clip-path-slant">
                              {t('private.btn.request')}
                            </button>

                            <div className="mt-6 pt-6 border-t border-mat-700 space-y-3">
                               <div className="flex justify-between text-xs font-bold">
                                  <span className="text-gray-500">{t('private.rental_fee')}</span>
                                  <span className="text-white">€{quote.rentalCost}</span>
                               </div>
                               <div className="flex justify-between text-xs font-bold">
                                  <span className="text-gray-500">{t('private.consumables')}</span>
                                  <span className="text-white">€{quote.consumableRevenue}</span>
                               </div>
                               <div className="flex justify-between text-xs font-bold text-green-500">
                                  <span>{t('private.discount_applied')}</span>
                                  <span>-€{quote.discount}</span>
                               </div>
                            </div>
                         </form>
                      </div>
                   </div>

                </div>
              )}

              {/* ================= PROMOTER / COLLAB FORM ================= */}
              {activeTab === 'promoter' && (
                <form onSubmit={handleSubmit} className="max-w-3xl mx-auto space-y-6 animate-fade-in bg-mat-800 p-10 border-2 border-mat-700 shadow-2xl rounded-lg">
                   <div className="text-center mb-10">
                     <h2 className="text-3xl font-black text-white uppercase tracking-tighter mb-2">{t('private.promoter.title')}</h2>
                     <p className="text-gray-500">{t('private.promoter.desc')}</p>
                   </div>

                   <div className="grid md:grid-cols-2 gap-8">
                      <div>
                        <label className="block text-xs font-bold text-mat-500 uppercase tracking-widest mb-2">{t('private.promoter.collective')}</label>
                        <input required type="text" name="collectiveName" value={promoterForm.collectiveName} onChange={handlePromoterChange} className="w-full bg-mat-900 border border-mat-700 text-white p-4 focus:border-mat-500 outline-none" />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-mat-500 uppercase tracking-widest mb-2">{t('private.promoter.contact')}</label>
                        <input required type="text" name="contactName" value={promoterForm.contactName} onChange={handlePromoterChange} className="w-full bg-mat-900 border border-mat-700 text-white p-4 focus:border-mat-500 outline-none" />
                      </div>
                   </div>

                   <div>
                      <label className="block text-xs font-bold text-mat-500 uppercase tracking-widest mb-2">{t('private.label.email')}</label>
                      <input required type="email" name="email" value={promoterForm.email} onChange={handlePromoterChange} className="w-full bg-mat-900 border border-mat-700 text-white p-4 focus:border-mat-500 outline-none" />
                   </div>

                   <div className="grid md:grid-cols-2 gap-8">
                      <div>
                        <label className="block text-xs font-bold text-mat-500 uppercase tracking-widest mb-2">{t('private.promoter.link')}</label>
