                      </div>
                   </div>

                   <div>
                      <label className="block text-xs font-bold text-mat-500 uppercase tracking-widest mb-2">{t('private.promoter.music')}</label>
                      <textarea required name="concept" value={promoterForm.concept} onChange={handlePromoterChange} className="w-full bg-mat-900 border border-mat-700 text-white p-4 h-40 focus:border-mat-500 outline-none resize-none" placeholder="Concept, DJs, Sound..."></textarea>
                   </div>

                   <button type="submit" className="w-full bg-mat-cream hover:bg-white text-mat-900 font-black py-5 uppercase tracking-widest transition-all shadow-lg clip-path-slant">
