  const conditions = ['All', 'Mint', 'NM', 'VG+', 'VG'];
  const formats = ['All', 'LP', '12"', '7"'];

  const filteredRecords = useMemo(() => {
    return MOCK_RECORDS.filter(record => {
      const matchesSearch = record.artist.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            record.title.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesGenre = selectedGenre === 'All' || record.genre === selectedGenre;
      const matchesCondition = selectedCondition === 'All' || record.condition === selectedCondition;
      const matchesFormat = selectedFormat === 'All' || record.format === selectedFormat;

      return matchesSearch && matchesGenre && matchesCondition && matchesFormat;
    });
  }, [searchTerm, selectedGenre, selectedCondition, selectedFormat]);

  const resetFilters = () => {
    setSearchTerm('');
    setSelectedGenre('All');
    setSelectedCondition('All');
    setSelectedFormat('All');
  };

  const hasActiveFilters = selectedGenre !== 'All' || selectedCondition !== 'All' || selectedFormat !== 'All' || searchTerm !== '';

  return (
    <div className="min-h-screen bg-mat-900 text-mat-cream">
      <SEO titleKey="seo.records.title" descriptionKey="seo.records.description" />

      {/* Shop Header */}
      <div className="bg-mat-800 py-12 border-b border-mat-700">
