                type="text" 
                placeholder={t('records.search_placeholder')}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full lg:w-64 bg-mat-800 border border-mat-700 text-white pl-10 pr-4 py-3 focus:outline-none focus:border-mat-500 transition-colors uppercase text-sm placeholder-gray-600"
