import React, { useEffect } from 'react';
import { useLanguage } from '../context/LanguageContext';

interface SEOProps {
  titleKey: string;
  descriptionKey: string;
}

export const SEO: React.FC<SEOProps> = ({ titleKey, descriptionKey }) => {
  const { t } = useLanguage();

  useEffect(() => {
    const siteName = "Mat32 Disco Bar & Records";
    const pageTitle = `${t(titleKey)} | ${siteName}`;
    const pageDescription = t(descriptionKey);

    // Standard Tags
    document.title = pageTitle;

    let metaDescription = document.querySelector('meta[name="description"]');
    if (!metaDescription) {
      metaDescription = document.createElement('meta');
      metaDescription.setAttribute('name', 'description');
      document.head.appendChild(metaDescription);
    }
    metaDescription.setAttribute('content', pageDescription);

    // Open Graph / Social Media Tags
    const updateOrCreateMeta = (property: string, content: string) => {
      let meta = document.querySelector(`meta[property="${property}"]`);
      if (!meta) {
        meta = document.createElement('meta');
        meta.setAttribute('property', property);
        document.head.appendChild(meta);
      }
      meta.setAttribute('content', content);
    };

    updateOrCreateMeta('og:title', pageTitle);
    updateOrCreateMeta('og:description', pageDescription);
    updateOrCreateMeta('og:site_name', siteName);
    updateOrCreateMeta('og:type', 'website');
    updateOrCreateMeta('og:locale', 'es_ES');

  }, [t, titleKey, descriptionKey]);

  return null;
};

