import React, { useState, useEffect } from 'react';
import { Wine, Users, Clock, CheckCircle, Martini, Info, Sparkles, AlertTriangle, Shield, Music2, Calculator } from 'lucide-react';
import { SEO } from '../components/SEO';
import { useLanguage } from '../context/LanguageContext';

type EventType = 'private' | 'promoter';

export const PrivateEvents: React.FC = () => {
  const { t } = useLanguage();
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [eventType, setEventType] = useState<EventType>('private');

  const [privateForm, setPrivateForm] = useState({
    name: '', 
    email: '', 
    date: new Date().toISOString().split('T')[0],
    duration: 4, 
    guests: 40, 
    ticketsPerGuest: 2,
    hasTech: false,
    hasSecurity: false
  });

  const [quote, setQuote] = useState({
    rentalCost: 0, 
    consumableRevenue: 0, 
    extraCosts: 0,
    discount: 0, 
    finalTotal: 0,
    pricePerPerson: 0, 
    totalDrinks: 0, 
    isWeekend: false
  });

  useEffect(() => {
    const calculateQuote = () => {
      const day = new Date(privateForm.date).getDay();
      const isWeekend = day === 5 || day === 6;

      // Rates based on type
      let hourlyRate = isWeekend ? 100 : 60;
      if (eventType === 'promoter') {
        hourlyRate = isWeekend ? 150 : 120; // Professional fee
      }

      const rental = privateForm.duration * hourlyRate;
      const totalDrinks = privateForm.guests * privateForm.ticketsPerGuest;
      const drinksRevenue = totalDrinks * 10;

      // Extras
      let extras = 0;
      if (privateForm.hasTech) extras += 150;
      if (privateForm.hasSecurity) extras += 120;
      if (eventType === 'promoter' && !privateForm.hasSecurity) extras += 120; // Security is mandatory for promoters

      // Discount logic for private parties (drinks discount rental)
      const discount = eventType === 'private' ? Math.min(rental, drinksRevenue * 0.5) : 0;

      const final = Math.max(0, rental - discount) + drinksRevenue + extras;

      setQuote({
        rentalCost: rental, 
        consumableRevenue: drinksRevenue, 
        extraCosts: extras,
        discount,
        finalTotal: final, 
        pricePerPerson: final / privateForm.guests,
        totalDrinks, 
        isWeekend
      });
    };
    calculateQuote();
  }, [privateForm, eventType]);

  return (
    <div className="min-h-screen bg-mat-900 flex flex-col">
      <SEO titleKey="seo.private.title" descriptionKey="seo.private.description" />

      {/* Hero Header */}
      <div className="bg-mat-800 py-16 border-b border-mat-700">
        <div className="container mx-auto px-6 text-center">
          <h1 className="text-5xl md:text-7xl font-black uppercase tracking-tighter text-white mb-4">{t('private.hero.title')}</h1>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">{t('private.hero.desc')}</p>
        </div>
      </div>

      <div className="container mx-auto px-6 py-12 max-w-6xl">
        {/* Toggle Type */}
        <div className="flex justify-center mb-12">
           <div className="bg-mat-800 p-1 border-2 border-mat-700 rounded-full flex overflow-hidden shadow-xl">
              <button 
                onClick={() => setEventType('private')}
                className={`px-8 py-3 rounded-full text-xs font-black uppercase tracking-widest transition-all ${eventType === 'private' ? 'bg-mat-500 text-white shadow-lg' : 'text-gray-500 hover:text-white'}`}
              >
                {t('private.type.private')}
              </button>
              <button 
                onClick={() => setEventType('promoter')}
                className={`px-8 py-3 rounded-full text-xs font-black uppercase tracking-widest transition-all ${eventType === 'promoter' ? 'bg-mat-500 text-white shadow-lg' : 'text-gray-500 hover:text-white'}`}
              >
                {t('private.type.promoter')}
              </button>
           </div>
        </div>

