import React, { useState } from 'react';
import { Calendar, Clock, MapPin, Check, Ticket, ListMusic, ExternalLink } from 'lucide-react';
import { Event } from '../types';
import { toggleRsvp } from '../services/geminiService';
import { useLanguage } from '../context/LanguageContext';

interface EventCardProps {
  event: Event;
}

export const EventCard: React.FC<EventCardProps> = ({ event }) => {
  const { t } = useLanguage();
  const [isAttending, setIsAttending] = useState(false);
  const [attendeeCount, setAttendeeCount] = useState(event.attendees);

  const isFree = event.price === 0;

  const handleRsvp = () => {
    // Only toggle attending status for free events (Guest List)
    if (isFree) {
      const newStatus = !isAttending;
      setIsAttending(newStatus);
      setAttendeeCount(prev => newStatus ? prev + 1 : prev - 1);

      // Sync with AI context
      toggleRsvp(event.title, newStatus);
    } else {
      // For paid events, navigate to ticket link
      if (event.ticketLink) {
        window.open(event.ticketLink, '_blank');
      }
    }
  };

  return (
    <article className={`
      bg-mat-800 
      border-2 ${isAttending && isFree ? 'border-mat-accent' : 'border-mat-700'} 
      shadow-xl hover:shadow-2xl hover:shadow-mat-900/80
      hover:-translate-y-1 hover:scale-[1.01] hover:border-mat-500
      transition-all duration-500 ease-out
      flex flex-col md:flex-row 
      overflow-hidden group relative 
      w-full
    `}>

      {/* "Going" Badge Overlay for Guest List */}
      {isAttending && isFree && (
        <div className="absolute top-4 right-4 z-20 bg-mat-accent text-mat-900 px-4 py-1.5 font-black uppercase text-[10px] tracking-widest animate-fade-in shadow-xl flex items-center gap-2">
          <Check className="w-3 h-3" /> {t('events.card.onthelist')}
        </div>
      )}

      {/* Price Badge Overlay */}
      <div className={`absolute top-4 left-4 z-20 px-4 py-1.5 font-black uppercase text-[10px] tracking-widest shadow-xl border-2 ${isFree ? 'bg-green-600 border-green-400 text-white' : 'bg-mat-500 border-mat-400 text-white'}`}>
        {isFree ? t('events.card.free') : `$${event.price} ${t('events.card.tickets')}`}
      </div>

      {/* Image Section - Locked Aspect Ratio */}
      <div className="md:w-[40%] relative aspect-[16/10] md:aspect-auto overflow-hidden bg-mat-900">
        <img 
          src={event.imageUrl} 
          alt={event.title} 
          className={`w-full h-full object-cover transition-all duration-1000 ease-in-out ${isAttending && isFree ? 'grayscale-0' : 'grayscale group-hover:grayscale-0 scale-100 group-hover:scale-110'}`}
        />
        {/* Category Tag */}
        <div className="absolute bottom-0 left-0 bg-mat-900/90 text-mat-500 text-[10px] font-black px-5 py-2 uppercase tracking-[0.2em] backdrop-blur-md border-t-2 border-r-2 border-mat-800">
          {event.category}
        </div>
      </div>

      {/* Content Section */}
      <div className="p-8 md:w-[60%] flex flex-col relative z-10 justify-between">

        <div>
          {/* Date */}
          <div className="flex items-center text-mat-500 font-black text-[10px] uppercase tracking-[0.3em] mb-4">
            <Calendar className="w-3 h-3 mr-2" />
            {event.date}
          </div>

          {/* Title */}
          <h3 className="text-2xl md:text-4xl font-black text-mat-cream uppercase leading-[0.9] mb-4 group-hover:text-mat-500 transition-colors duration-300">
            {event.title}
          </h3>

          {/* Description */}
          <p className="text-gray-400 text-sm leading-relaxed border-l-2 border-mat-700 pl-6 mb-8 line-clamp-2 group-hover:text-gray-300 transition-colors font-light">
            {event.description}
          </p>
        </div>

        {/* Footer Actions */}
        <div className="pt-6 border-t-2 border-mat-700/30 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
          {/* Info Stats */}
          <div className="flex flex-col gap-2 text-xs text-gray-400 font-bold uppercase tracking-wider">
            <div className="flex items-center group/info">
              <Clock className="w-4 h-4 mr-3 text-mat-600 group-hover/info:text-mat-500 transition-colors" />
              {event.time}
            </div>
            <div className="flex items-center group/info">
              <MapPin className="w-4 h-4 mr-3 text-mat-600 group-hover/info:text-mat-500 transition-colors" />
              {event.location}
            </div>
            <div className="text-[10px] text-mat-500 mt-1 font-black flex items-center gap-2">
               <span className="w-1.5 h-1.5 bg-mat-500 rounded-full animate-pulse"></span>
               {attendeeCount} {isFree ? t('events.card.attending') : t('events.card.sold')}
            </div>
          </div>

          {/* Action Button */}
          <button 
            onClick={handleRsvp}
            className={`
              px-8 py-5 
              font-black uppercase text-[10px] tracking-[0.2em] 
              flex items-center justify-center gap-2 
              transition-all duration-300 
              w-full sm:w-auto
              border-2
              shadow-xl
              hover:-translate-y-1 hover:shadow-mat-500/20
              clip-path-slant
              ${
                isFree 
                  ? isAttending
                    ? 'bg-mat-accent border-mat-accent text-mat-900' 
                    : 'bg-transparent border-mat-500 text-mat-500 hover:bg-mat-500 hover:text-white'
                  : 'bg-mat-500 border-mat-500 text-white hover:bg-mat-400 hover:border-mat-400'
              }
            `}
          >
            {isFree ? (
              isAttending ? (
                <>
                  <Check className="w-4 h-4" /> {t('events.card.onthelist')}
                </>
              ) : (
                <>
                  <ListMusic className="w-4 h-4" /> {t('events.card.guestlist')}
                </>
              )
            ) : (
              <>
                <Ticket className="w-4 h-4" /> {t('events.card.get_tickets')} <ExternalLink className="w-3 h-3 ml-1" />
              </>
            )}
          </button>
        </div>
      </div>
    </article>
  );
};

