import React, { useState } from 'react';
import { Calendar, Clock, MapPin, Check, Ticket, ListMusic, ExternalLink } from 'lucide-react';
import { Event } from '../types';
import { toggleRsvp } from '../services/geminiService';
import { useLanguage } from '../context/LanguageContext';

interface EventCardProps {
  event: Event;
}

export const EventCard: React.FC<EventCardProps> = ({ event }) => {
  const { t } = useLanguage();
  const [isAttending, setIsAttending] = useState(false);
  const [attendeeCount, setAttendeeCount] = useState(event.attendees);

  const isFree = event.price === 0;

  const handleRsvp = () => {
    if (isFree) {
      const newStatus = !isAttending;
      setIsAttending(newStatus);
      setAttendeeCount(prev => newStatus ? prev + 1 : prev - 1);
      toggleRsvp(event.title, newStatus);
    } else {
      if (event.ticketLink) {
        window.open(event.ticketLink, '_blank');
      }
    }
  };

  return (
    <article className={`
      bg-mat-800 
      border-2 ${isAttending && isFree ? 'border-mat-accent' : 'border-mat-700'} 
      shadow-xl 
      hover:shadow-mat-500/20 hover:-translate-y-1 hover:scale-[1.01] hover:border-mat-500
      transition-all duration-500 ease-out
      flex flex-col md:flex-row 
      overflow-hidden group relative 
      w-full min-h-[280px]
    `}>

      {/* Badges */}
      {isAttending && isFree && (
        <div className="absolute top-4 right-4 z-20 bg-mat-accent text-mat-900 px-4 py-1 font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center gap-2">
          <Check className="w-3 h-3" /> {t('events.card.onthelist')}
        </div>
      )}

      <div className={`absolute top-4 left-4 z-20 px-4 py-1 font-black uppercase text-[10px] tracking-widest shadow-xl border-2 ${isFree ? 'bg-green-600 border-green-400' : 'bg-mat-500 border-mat-400'}`}>
        {isFree ? t('events.card.free') : `$${event.price}`}
      </div>

      {/* Image Section - Strict 16:9 Aspect Ratio */}
      <div className="md:w-2/5 relative aspect-video md:aspect-auto overflow-hidden bg-mat-900 flex-shrink-0">
        <img 
          src={event.imageUrl} 
          alt={event.title} 
          className="w-full h-full object-cover transition-all duration-1000 grayscale group-hover:grayscale-0 scale-100 group-hover:scale-110"
        />
        <div className="absolute bottom-0 left-0 bg-mat-900/90 text-mat-500 text-[10px] font-black px-4 py-2 uppercase tracking-[0.2em] border-t border-r border-mat-700">
          {event.category}
        </div>
      </div>

      {/* Content Section */}
      <div className="p-8 md:w-3/5 flex flex-col justify-between">
        <div className="mb-6">
          <div className="flex items-center text-mat-500 font-bold text-[10px] uppercase tracking-[0.3em] mb-3">
            <Calendar className="w-3 h-3 mr-2" />
            {event.date}
          </div>

          <h3 className="text-2xl md:text-3xl font-black text-mat-cream uppercase leading-tight mb-4 group-hover:text-mat-500 transition-colors">
            {event.title}
          </h3>

          <p className="text-gray-400 text-sm leading-relaxed border-l-2 border-mat-700 pl-4 mb-2 line-clamp-2">
            {event.description}
          </p>
        </div>

        <div className="pt-6 border-t border-mat-700/50 flex flex-col sm:flex-row sm:items-center justify-between gap-6 mt-auto">
          <div className="flex flex-col gap-1.5 text-[10px] text-gray-500 font-bold uppercase tracking-wider">
            <div className="flex items-center">
              <Clock className="w-3.5 h-3.5 mr-2 text-mat-700" />
              {event.time}
            </div>
            <div className="flex items-center">
              <MapPin className="w-3.5 h-3.5 mr-2 text-mat-700" />
              {event.location}
            </div>
            <div className="text-mat-500 mt-1 flex items-center gap-2">
               <span className="w-1.5 h-1.5 bg-mat-500 rounded-full"></span>
               {attendeeCount} {isFree ? t('events.card.attending') : t('events.card.sold')}
            </div>
          </div>

          <button 
            onClick={handleRsvp}
            className={`
              px-8 py-4 
              font-black uppercase text-[10px] tracking-widest 
              flex items-center justify-center gap-2 
              transition-all duration-300 
              border-2 clip-path-slant
              ${
                isFree 
                  ? isAttending
                    ? 'bg-mat-accent border-mat-accent text-mat-900' 
                    : 'bg-transparent border-mat-500 text-mat-500 hover:bg-mat-500 hover:text-white'
                  : 'bg-mat-500 border-mat-500 text-white hover:bg-mat-400 hover:border-mat-400'
              }
            `}
          >
            {isFree ? (
              isAttending ? <Check className="w-4 h-4" /> : <ListMusic className="w-4 h-4" />
            ) : (
              <Ticket className="w-4 h-4" />
            )}
            {isFree ? (isAttending ? t('events.card.onthelist') : t('events.card.guestlist')) : t('events.card.get_tickets')}
          </button>
        </div>
      </div>
    </article>
  );
};

import React, { useState, useEffect } from 'react';
