                <div className="bg-black/50 p-3 text-center border-b border-mat-800 uppercase text-[10px] font-black tracking-[0.2em] text-gray-500 flex items-center justify-center gap-2">
                  {quote.isWeekend ? <Sparkles className="w-3 h-3 text-mat-accent" /> : <Clock className="w-3 h-3" />}
