                              className={`py-5 border-2 font-black transition-all text-sm tracking-widest ${privateForm.ticketsPerGuest === v ? 'bg-mat-500 border-mat-500 text-white shadow-2xl scale-105 z-10' : 'bg-mat-800 border-mat-700 text-gray-500 hover:text-white hover:border-mat-500'}`}
