    totalDrinks: 0, 
    isWeekend: false
  });

  useEffect(() => {
    const calculateQuote = () => {
      const day = new Date(privateForm.date).getDay();
      const isWeekend = day === 5 || day === 6;

      let hourlyRate = isWeekend ? 80 : 50; 
      const rental = privateForm.duration * hourlyRate;
      const totalDrinks = privateForm.guests * privateForm.ticketsPerGuest;
      const drinksRevenue = totalDrinks * 8; 

      const discount = Math.min(rental, drinksRevenue * 0.4);
      const final = Math.max(0, rental - discount) + drinksRevenue;

      setQuote({
        rentalCost: rental, 
        consumableRevenue: drinksRevenue, 
        discount,
        finalTotal: final, 
        pricePerPerson: final / privateForm.guests,
        totalDrinks, 
        isWeekend
      });
    };
    calculateQuote();
  }, [privateForm]);

  return (
    <div className="min-h-screen bg-mat-900 flex flex-col">
