import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { translations } from '../translations';

type Language = 'en' | 'es';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  toggleLanguage: () => void;
  t: (key: string) => string;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguage] = useState<Language>('en');

  useEffect(() => {
    // Try to get saved language first
    const savedLang = localStorage.getItem('mat32_lang') as Language;
    if (savedLang && (savedLang === 'en' || savedLang === 'es')) {
      setLanguage(savedLang);
    } else {
      // Auto-detect language if no saved preference
      const browserLang = navigator.language.split('-')[0];
      if (browserLang === 'es') {
        setLanguage('es');
      }
    }
  }, []);

  const toggleLanguage = () => {
    setLanguage(prev => {
      const next = prev === 'en' ? 'es' : 'en';
      localStorage.setItem('mat32_lang', next);
      return next;
    });
  };

  const t = (key: string): string => {
    // @ts-ignore
    return translations[language][key] || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, toggleLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { MOCK_EVENTS, MOCK_POSTS } from '../constants';

// Initialize the API client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Track user RSVPs in memory
const userRsvps = new Set<string>();

export const toggleRsvp = (eventTitle: string, isAttending: boolean) => {
  if (isAttending) {
    userRsvps.add(eventTitle);
  } else {
    userRsvps.delete(eventTitle);
  }
};

// Construct a system instruction that gives the AI context about the website content
const getSystemInstruction = (language: 'en' | 'es') => `
You are the Bar Manager and Head of Vinyl at "Mat32", a vintage-style disco bar and record store in Valencia, Spain.
Your vibe is cool, knowledgeable about music (especially disco, funk, house, and jazz), and welcoming.

IMPORTANT: You must respond in ${language === 'es' ? 'Spanish' : 'English'}.

Your help topics:
- Event details (gigs, open decks).
- Record store inquiries (rare finds, genres).
- Booking tables or signing up for Open Decks.

Current Upcoming Events:
${JSON.stringify(MOCK_EVENTS.map(e => `${e.title} on ${e.date} at ${e.time} (${e.category}) - ${e.description}`), null, 2)}

Recent Community Highlights:
${JSON.stringify(MOCK_POSTS.map(p => `${p.author} said: "${p.content}"`), null, 2)}

Tone: Vintage cool, relaxed, helpful. Use terms like "spinning", "tracks", "groove" (or Spanish equivalents like "pinchando", "temas", "ritmo").
Keep responses concise.
If asked about the Open Decks, tell them to use the form on the website.
`;

let chatSession: Chat | null = null;
let currentChatLang: 'en' | 'es' | null = null;

export const getChatSession = (language: 'en' | 'es'): Chat => {
  if (!chatSession || currentChatLang !== language) {
    chatSession = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: getSystemInstruction(language),
      },
    });
    currentChatLang = language;
  }
  return chatSession;
};

export const sendMessageToGemini = async (message: string, language: 'en' | 'es'): Promise<string> => {
  try {
    const chat = getChatSession(language);

    // Inject dynamic context about the user's RSVPs into the message
    const rsvpContext = userRsvps.size > 0 
      ? `[System Note: The user has RSVP'd to the following events: ${Array.from(userRsvps).join(', ')}. If they ask about their schedule, remind them of these.]` 
      : "";

    const fullMessage = `${rsvpContext} ${message}`;

    const result: GenerateContentResponse = await chat.sendMessage({ message: fullMessage });
    return result.text || (language === 'es' ? "La aguja ha saltado. ¿Puedes repetirlo?" : "The turntable skipped. Can you say that again?");
  } catch (error) {
    console.error("Gemini API Error:", error);
    return language === 'es' 
      ? "Perdona, la música está muy alta y no te oigo bien. (Error de conexión)" 
      : "Sorry, the music is too loud, I can't hear you right now. (Connection Error)";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Disc, Loader2 } from 'lucide-react';
import { sendMessageToGemini } from '../services/geminiService';
import { ChatMessage } from '../types';
import { useLanguage } from '../context/LanguageContext';

export const AIChat: React.FC = () => {
  const { t, language } = useLanguage();
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Initialize welcome message when language changes or on first load
  useEffect(() => {
    setMessages([
      { role: 'model', text: t('chat.welcome') }
    ]);
  }, [language]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const responseText = await sendMessageToGemini(userMsg.text, language);

    setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSend();
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end font-sans">
      {/* Chat Window */}
