function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const VoiceAssistant: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { t, language } = useLanguage();
  const [status, setStatus] = useState<'connecting' | 'listening' | 'idle'>('connecting');
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    let scriptProcessor: ScriptProcessorNode | null = null;
    let stream: MediaStream | null = null;

    const startSession = async () => {
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

        stream = await navigator.mediaDevices.getUserMedia({ audio: true });

        const sessionPromise = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-12-2025',
          callbacks: {
            onopen: () => {
              setStatus('listening');
              const source = inputAudioContextRef.current!.createMediaStreamSource(stream!);
              scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);

              scriptProcessor.onaudioprocess = (e) => {
                const inputData = e.inputBuffer.getChannelData(0);
                const l = inputData.length;
                const int16 = new Int16Array(l);
                for (let i = 0; i < l; i++) {
                  int16[i] = inputData[i] * 32768;
                }
                const pcmBlob = {
                  data: encode(new Uint8Array(int16.buffer)),
                  mimeType: 'audio/pcm;rate=16000',
                };
                sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
              };

              source.connect(scriptProcessor);
              scriptProcessor.connect(inputAudioContextRef.current!.destination);
            },
            onmessage: async (message) => {
              const audioBase64 = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
              if (audioBase64 && audioContextRef.current) {
                const audioBuffer = await decodeAudioData(
                  decode(audioBase64),
                  audioContextRef.current,
                  24000,
                  1
                );
                const source = audioContextRef.current.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContextRef.current.destination);

                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioContextRef.current.currentTime);
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
                source.onended = () => sourcesRef.current.delete(source);
              }

              if (message.serverContent?.interrupted) {
                sourcesRef.current.forEach(s => s.stop());
                sourcesRef.current.clear();
                nextStartTimeRef.current = 0;
              }
            },
            onclose: () => onClose(),
            onerror: (e) => console.error('Voice Assistant Error:', e)
          },
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
              voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
            },
            systemInstruction: `You are the Mat32 Assistant. You are currently in a real-time voice call with a customer. Be cool, concise, and helpful. Use a casual disco bar vibe. Language: ${language === 'es' ? 'Spanish' : 'English'}.`
          }
        });

        sessionRef.current = await sessionPromise;
      } catch (err) {
        console.error('Failed to start voice assistant:', err);
        onClose();
      }
    };

    startSession();

    return () => {
      if (scriptProcessor) scriptProcessor.disconnect();
      if (stream) stream.getTracks().forEach(t => t.stop());
      if (audioContextRef.current) audioContextRef.current.close();
      if (inputAudioContextRef.current) inputAudioContextRef.current.close();
      if (sessionRef.current) sessionRef.current.close();
    };
  }, [language, onClose]);

  return (
    <div className="absolute inset-0 bg-mat-900/95 backdrop-blur-xl z-50 flex flex-col items-center justify-center p-8 text-center animate-fade-in rounded-t-lg border-t-2 border-mat-500">
      <div className="relative mb-12">
        <div className={`w-32 h-32 bg-mat-800 rounded-full border-4 border-mat-700 flex items-center justify-center transition-all duration-500 ${status === 'listening' ? 'scale-110 border-mat-500 shadow-[0_0_50px_rgba(234,88,12,0.3)]' : ''}`}>
          {status === 'connecting' ? (
            <Loader2 className="w-12 h-12 text-mat-500 animate-spin" />
          ) : (
            <Disc className={`w-16 h-16 text-mat-500 ${status === 'listening' ? 'animate-spin-slow' : ''}`} />
          )}
        </div>
        {status === 'listening' && (
          <div className="absolute inset-0 -z-10 animate-ping bg-mat-500/20 rounded-full"></div>
        )}
      </div>

      <h2 className="text-2xl font-black text-white uppercase tracking-tighter mb-2">
        {status === 'connecting' ? t('ai.voice.connecting') : t('ai.voice.listening')}
      </h2>
      <p className="text-gray-500 text-xs uppercase tracking-widest mb-12">Mat32 Live Audio Session</p>

      <div className="flex gap-4">
        <button 
          onClick={onClose}
          className="bg-red-600 hover:bg-red-500 text-white px-8 py-4 rounded-full font-black uppercase tracking-widest flex items-center gap-2 transition-all shadow-xl"
        >
          <Square className="w-4 h-4" /> {t('ai.voice.stop')}
        </button>
      </div>

      <div className="mt-12 flex gap-1 h-8 items-end">
        {[...Array(12)].map((_, i) => (
          <div 
            key={i} 
            className={`w-1 bg-mat-500 transition-all duration-150 ${status === 'listening' ? 'animate-pulse' : 'h-1'}`}
            style={{ 
              height: status === 'listening' ? `${Math.random() * 80 + 20}%` : '4px',
              animationDelay: `${i * 0.1}s` 
            }}
          ></div>
        ))}
      </div>
    </div>
  );
};

