      setGeneratedPoster(imageUrl);
    } catch (err) {
      alert("Failed to generate poster. Check your connection.");
    } finally {
      setIsGenerating(false);
    }
  };

  const filteredPosts = selectedTag 
    ? MOCK_POSTS.filter(post => post.tags.includes(selectedTag))
    : MOCK_POSTS;

  return (
    <div className="min-h-screen bg-mat-900">
      <SEO titleKey="seo.community.title" descriptionKey="seo.community.description" />

      <div className="bg-mat-800 py-12 border-b border-mat-700">
        <div className="container mx-auto px-6 text-center">
          <h1 className="text-4xl md:text-5xl font-black uppercase tracking-tighter text-white mb-4">{t('community.title')}</h1>
          <p className="text-gray-400 text-lg">{t('community.subtitle')}</p>
        </div>
      </div>

      <div className="container mx-auto px-6 py-12">
        {/* AI Poster Maker Section */}
        <section className="mb-20 bg-mat-800 border-2 border-mat-700 p-8 md:p-12 shadow-2xl relative overflow-hidden">
           <div className="absolute top-0 right-0 w-64 h-64 bg-mat-500/10 rounded-full blur-3xl pointer-events-none"></div>
           <div className="flex flex-col lg:flex-row gap-12 items-center">
              <div className="flex-1 space-y-6">
                 <div className="flex items-center gap-4">
                    <Sparkles className="w-8 h-8 text-mat-500" />
                    <h2 className="text-3xl font-black text-white uppercase tracking-tighter">{t('ai.poster.title')}</h2>
                 </div>
                 <p className="text-gray-400 leading-relaxed text-lg italic">
                    {t('ai.poster.desc')}
                 </p>
                 <div className="space-y-4">
                    <textarea 
                      value={posterPrompt}
                      onChange={(e) => setPosterPrompt(e.target.value)}
                      placeholder={t('ai.poster.prompt')}
                      className="w-full bg-mat-900 border-2 border-mat-700 p-6 text-white outline-none focus:border-mat-500 transition-colors h-32 resize-none"
                    />
                    <button 
                      onClick={handleGeneratePoster}
                      disabled={isGenerating || !posterPrompt.trim()}
                      className="w-full lg:w-auto px-12 py-4 bg-mat-500 hover:bg-mat-400 disabled:opacity-50 text-white font-black uppercase tracking-widest transition-all shadow-xl flex items-center justify-center gap-3 clip-path-slant"
                    >
                       {isGenerating ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />}
                       {isGenerating ? t('ai.poster.loading') : t('ai.poster.btn')}
                    </button>
                 </div>
              </div>
              <div className="w-full lg:w-80 aspect-[3/4] bg-mat-900 border-4 border-mat-700 shadow-inner flex items-center justify-center relative group">
                 {generatedPoster ? (
                    <>
                      <img src={generatedPoster} alt="AI Poster" className="w-full h-full object-cover animate-fade-in" />
                      <a 
                        href={generatedPoster} 
                        download="mat32-poster.png"
                        className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                         <div className="bg-mat-500 text-white p-4 rounded-full">
                           <Download className="w-6 h-6" />
                         </div>
                      </a>
