                 ) : (
                    <div className="text-center p-8">
                       <ImageIcon className="w-16 h-16 text-mat-700 mx-auto mb-4" />
                       <p className="text-xs text-gray-600 font-black uppercase tracking-widest">PREVIEW AREA</p>
                    </div>
                 )}
              </div>
           </div>
        </section>

        <div className="grid lg:grid-cols-3 gap-12">

          {/* Left Column: Text Feed */}
          <div className="lg:col-span-2">
             <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-2">
                   <MessageCircle className="text-mat-500" />
                   <h2 className="text-2xl font-bold text-white uppercase tracking-wider">{t('community.feed')}</h2>
                </div>

                {selectedTag && (
                   <button 
                     onClick={() => setSelectedTag(null)}
                     className="text-xs font-bold text-mat-500 uppercase tracking-widest border border-mat-500 px-3 py-1 hover:bg-mat-500 hover:text-white transition-colors flex items-center gap-2"
                   >
                     {t('community.filter')}: {selectedTag} <X className="w-3 h-3" />
                   </button>
                )}
             </div>

            {/* New Post Input */}
            <div className="bg-[#1f1c1a] p-6 border border-mat-700 mb-12 shadow-lg relative">
              <div className="absolute top-0 left-0 w-full h-1 bg-mat-500"></div>
              <textarea 
                placeholder={t('community.post_placeholder')}
                className="w-full bg-mat-900 text-white placeholder-gray-600 focus:outline-none p-4 border border-mat-700 min-h-[100px] resize-none mb-4"
              />
              <div className="flex justify-between items-center">
                <div className="text-xs text-gray-500 uppercase tracking-wider">{t('community.guest')}</div>
                <button className="px-8 py-2 bg-mat-500 hover:bg-mat-400 text-white font-bold uppercase text-sm tracking-widest transition-colors">
                  {t('community.btn.post')}
                </button>
              </div>
            </div>

            {/* Feed */}
            <div className="space-y-8">
              {filteredPosts.length > 0 ? (
                filteredPosts.map(post => (
                  <div key={post.id} className="bg-mat-800 p-6 border-l-2 border-mat-700 hover:border-mat-500 transition-colors group">
                    <div className="flex items-center gap-4 mb-4">
                      <img src={post.avatar} alt={post.author} className="w-12 h-12 grayscale group-hover:grayscale-0 transition-all object-cover border border-mat-700" />
                      <div>
                        <h3 className="font-bold text-mat-cream uppercase tracking-wider text-sm">{post.author}</h3>
                        <span className="text-xs text-mat-500 font-mono">{post.timestamp}</span>
                      </div>
