                    <div className="flex justify-between items-center border-t border-mat-700 pt-4">
                      <div className="flex gap-2 flex-wrap">
                        {post.tags.map(tag => (
                          <button 
                            key={tag} 
                            onClick={() => setSelectedTag(tag === selectedTag ? null : tag)}
                            className={`text-xs transition-colors cursor-pointer ${
                              selectedTag === tag 
                                ? 'text-mat-500 font-bold underline underline-offset-4' 
