                <div className="bg-mat-800 p-8 text-center border border-mat-700">
                  <p className="text-gray-500">{t('community.empty')} <span className="text-mat-500 font-bold">{selectedTag}</span>.</p>
                  <button onClick={() => setSelectedTag(null)} className="text-white text-xs font-bold uppercase mt-4 underline">{t('community.clear')}</button>
