          {/* Right Column: Photo Gallery */}
          <div className="lg:col-span-1">
             <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-2">
                  <Camera className="text-mat-500" />
                  <h2 className="text-2xl font-bold text-white uppercase tracking-wider">{t('community.gallery')}</h2>
                </div>
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="text-xs font-bold text-mat-500 uppercase tracking-widest border border-mat-500 px-3 py-1 hover:bg-mat-500 hover:text-white transition-colors flex items-center gap-2"
                >
                  <Upload className="w-3 h-3" /> {t('community.upload')}
                </button>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileSelect} 
                  accept="image/*" 
                  className="hidden" 
                />
             </div>

             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-6">
               {photos.map(photo => (
                 <div key={photo.id} className="group relative bg-mat-800 p-2 border border-mat-700 shadow-lg transform hover:-rotate-1 transition-all duration-300">
                   <div className="relative overflow-hidden aspect-square">
                     <img 
                       src={photo.url} 
                       alt={photo.caption} 
                       className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" 
                     />
                     <div className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-black/90 to-transparent p-4 translate-y-full group-hover:translate-y-0 transition-transform duration-300">
                        <p className="text-white font-bold text-sm">{photo.caption}</p>
                        <p className="text-mat-500 text-xs uppercase tracking-wider">{photo.user}</p>
                     </div>
                   </div>
                   <div className="flex justify-between items-center mt-2 px-1">
                      <span className="text-xs text-gray-500 font-mono">{photo.timestamp}</span>
                      <button className="text-gray-500 hover:text-red-500 transition-colors flex items-center gap-1 text-xs">
                        <Heart className="w-3 h-3" /> {photo.likes}
                      </button>
                   </div>
                 </div>
               ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Calendar, Clock, MapPin, Check, Ticket, ListMusic } from 'lucide-react';
import { Event } from '../types';
import { toggleRsvp } from '../services/geminiService';
import { useLanguage } from '../context/LanguageContext';

interface EventCardProps {
  event: Event;
}

export const EventCard: React.FC<EventCardProps> = ({ event }) => {
  const { t } = useLanguage();
  const [isAttending, setIsAttending] = useState(false);
  const [attendeeCount, setAttendeeCount] = useState(event.attendees);

  const isFree = event.price === 0;

  const handleRsvp = () => {
    if (isFree) {
      const newStatus = !isAttending;
      setIsAttending(newStatus);
      setAttendeeCount(prev => newStatus ? prev + 1 : prev - 1);
      toggleRsvp(event.title, newStatus);
    } else if (event.ticketLink) {
      window.open(event.ticketLink, '_blank');
    }
  };

  return (
    <article className={`
      bg-mat-800 
      border-2 ${isAttending && isFree ? 'border-mat-accent shadow-mat-accent/10' : 'border-mat-700'} 
      shadow-xl 
      hover:shadow-mat-500/20 hover:-translate-y-1.5 hover:scale-[1.02] hover:border-mat-500
      transition-all duration-500 ease-out
      flex flex-col md:flex-row 
      overflow-hidden group relative 
      w-full
    `}>

      {/* Badges Overlay */}
      <div className="absolute top-4 right-4 z-20 flex flex-col gap-2 items-end">
        {isAttending && isFree && (
          <div className="bg-mat-accent text-mat-900 px-4 py-1.5 font-black uppercase text-[9px] tracking-[0.2em] shadow-xl flex items-center gap-2 animate-fade-in">
            <Check className="w-3 h-3" /> {t('events.card.onthelist')}
          </div>
        )}
        <div className={`px-4 py-1.5 font-black uppercase text-[9px] tracking-[0.2em] shadow-xl border-2 ${isFree ? 'bg-green-600 border-green-400' : 'bg-mat-500 border-mat-400'}`}>
          {isFree ? t('events.card.free') : `€${event.price}`}
        </div>
      </div>

      {/* Image Container - Rock solid 16:9 Aspect Ratio on mobile, fixed width on desktop */}
      <div className="md:w-[40%] xl:w-[35%] relative overflow-hidden bg-mat-900 flex-shrink-0">
        <div className="aspect-[16/9] md:aspect-auto md:h-full w-full">
          <img 
            src={event.imageUrl} 
            alt={event.title} 
            className="w-full h-full object-cover transition-all duration-[1500ms] grayscale group-hover:grayscale-0 scale-100 group-hover:scale-110"
          />
        </div>
        <div className="absolute bottom-0 left-0 bg-mat-900/95 text-mat-500 text-[9px] font-black px-5 py-2.5 uppercase tracking-[0.3em] border-t border-r border-mat-700 backdrop-blur-sm">
          {event.category}
        </div>
      </div>

      {/* Content Container */}
      <div className="p-8 md:p-10 flex flex-col justify-between flex-1">
        <div>
          <div className="flex items-center text-mat-500 font-black text-[9px] uppercase tracking-[0.4em] mb-4">
            <Calendar className="w-3 h-3 mr-2" />
            {event.date}
          </div>

          <h3 className="text-2xl md:text-3xl xl:text-4xl font-black text-mat-cream uppercase leading-[1] mb-5 group-hover:text-mat-500 transition-colors tracking-tighter">
            {event.title}
          </h3>

          <p className="text-gray-400 text-sm leading-relaxed border-l-2 border-mat-700/50 pl-6 mb-8 line-clamp-2 md:line-clamp-3 font-medium">
            {event.description}
          </p>
        </div>

        {/* Actions & Info Footer */}
        <div className="pt-6 border-t border-mat-700/40 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
          <div className="flex flex-col gap-2 text-[9px] text-gray-500 font-black uppercase tracking-[0.2em]">
            <div className="flex items-center group/info">
              <Clock className="w-4 h-4 mr-3 text-mat-700 group-hover/info:text-mat-500 transition-colors" />
              {event.time}
            </div>
            <div className="flex items-center group/info">
              <MapPin className="w-4 h-4 mr-3 text-mat-700 group-hover/info:text-mat-500 transition-colors" />
              {event.location}
            </div>
            <div className="text-mat-500 mt-1 flex items-center gap-2">
               <span className="w-1.5 h-1.5 bg-mat-500 rounded-full animate-pulse"></span>
               {attendeeCount} {isFree ? t('events.card.attending') : t('events.card.sold')}
            </div>
          </div>

          <button 
            onClick={handleRsvp}
            className={`
              px-8 py-4 
              font-black uppercase text-[10px] tracking-[0.2em] 
              flex items-center justify-center gap-3 
              transition-all duration-300 
              border-2 clip-path-slant
              shadow-lg
              hover:-translate-y-1 hover:shadow-mat-500/30
              ${
                isFree 
                  ? isAttending
                    ? 'bg-mat-accent border-mat-accent text-mat-900' 
                    : 'bg-transparent border-mat-500 text-mat-500 hover:bg-mat-500 hover:text-white'
                  : 'bg-mat-500 border-mat-500 text-white hover:bg-mat-400 hover:border-mat-400'
              }
            `}
          >
            {isFree ? (
              isAttending ? <Check className="w-5 h-5" /> : <ListMusic className="w-5 h-5" />
            ) : (
              <Ticket className="w-5 h-5" />
            )}
            {isFree ? (isAttending ? t('events.card.onthelist') : t('events.card.guestlist')) : t('events.card.get_tickets')}
          </button>
        </div>
      </div>
    </article>
  );
};

import React, { useState, useMemo } from 'react';
import { Search, Filter, Calendar as CalendarIcon, LayoutGrid, ChevronLeft, ChevronRight, Clock, MapPin } from 'lucide-react';
import { EventCard } from '../components/EventCard';
import { SEO } from '../components/SEO';
import { MOCK_EVENTS } from '../constants';
import { useLanguage } from '../context/LanguageContext';

export const Events: React.FC = () => {
  const { t } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [viewMode, setViewMode] = useState<'list' | 'calendar'>('list');

  // Set current date to today for accurate filtering and display
  const [currentDate, setCurrentDate] = useState(new Date());

  const categories = ['All', 'Disco', 'House', 'Live', 'Social'];

  const filteredEvents = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];

    return MOCK_EVENTS.filter(event => {
      // Logic: Only show events from today onwards
      const isFutureOrToday = event.date >= todayStr;
      if (!isFutureOrToday) return false;

      const matchesSearch = event.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            event.description.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = selectedCategory === 'All' || event.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchTerm, selectedCategory]);

  // Calendar Logic
  const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay(); // 0 = Sun, 1 = Mon...

  // Adjust for Monday start (1 = Mon ... 7 = Sun)
  const startingDayIndex = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const getEventsForDay = (day: number) => {
    const year = currentDate.getFullYear();
    const month = String(currentDate.getMonth() + 1).padStart(2, '0');
    const dateString = `${year}-${month}-${String(day).padStart(2, '0')}`;
    return filteredEvents.filter(e => e.date === dateString);
  };

  const monthName = currentDate.toLocaleString('default', { month: 'long' });
  const year = currentDate.getFullYear();

  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const emptyDays = Array.from({ length: startingDayIndex }, (_, i) => i);

  return (
    <div className="min-h-screen bg-mat-900 text-mat-cream">
      <SEO titleKey="seo.events.title" descriptionKey="seo.events.description" />

      <div className="bg-mat-800 py-12 border-b border-mat-700">
        <div className="container mx-auto px-6">
          <h1 className="text-5xl font-black uppercase tracking-tighter text-white mb-4">{t('events.title')}</h1>
          <p className="text-gray-400 max-w-xl text-lg">
            {t('events.subtitle')}
          </p>
        </div>
      </div>

      <div className="container mx-auto px-6 py-12">
        {/* Controls Bar */}
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center mb-8 gap-6 bg-mat-900 sticky top-20 z-30 py-4 border-b border-mat-800">
          <div className="flex items-center gap-2 text-mat-500 font-bold uppercase tracking-widest text-sm">
             <CalendarIcon className="w-4 h-4" /> {t('events.upcoming')}
          </div>

          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
            {/* View Toggle */}
            <div className="flex bg-mat-800 p-1 border border-mat-700">
              <button 
                onClick={() => setViewMode('list')}
                className={`p-2 flex items-center gap-2 text-xs font-bold uppercase tracking-wider transition-colors ${viewMode === 'list' ? 'bg-mat-500 text-white' : 'text-gray-400 hover:text-white'}`}
              >
                <LayoutGrid className="w-4 h-4" /> {t('events.view.list')}
              </button>
              <button 
                onClick={() => setViewMode('calendar')}
                className={`p-2 flex items-center gap-2 text-xs font-bold uppercase tracking-wider transition-colors ${viewMode === 'calendar' ? 'bg-mat-500 text-white' : 'text-gray-400 hover:text-white'}`}
              >
                <CalendarIcon className="w-4 h-4" /> {t('events.view.calendar')}
              </button>
            </div>

            {/* Search */}
            <div className="relative flex-grow md:flex-grow-0">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 w-4 h-4" />
              <input 
                type="text" 
                placeholder={t('events.search')}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full md:w-64 bg-mat-800 border border-mat-700 text-white pl-10 pr-4 py-3 focus:outline-none focus:border-mat-500 transition-colors uppercase text-sm placeholder-gray-600"
              />
            </div>

            {/* Filter */}
            <div className="relative">
               <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 w-4 h-4" />
               <select 
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className="w-full md:w-48 bg-mat-800 border border-mat-700 text-white pl-10 pr-8 py-3 focus:outline-none focus:border-mat-500 appearance-none cursor-pointer uppercase text-sm"
               >
                 {categories.map(cat => (
                   <option key={cat} value={cat}>{cat === 'All' ? t('events.filter.all') : cat}</option>
                 ))}
               </select>
            </div>
          </div>
        </div>

        {/* Content Area */}
        {viewMode === 'list' ? (
          filteredEvents.length > 0 ? (
            <div className="grid grid-cols-1 gap-8 animate-fade-in">
              {filteredEvents.map(event => (
                <EventCard key={event.id} event={event} />
              ))}
            </div>
          ) : (
            <EmptyState 
              reset={() => {setSearchTerm(''); setSelectedCategory('All');}} 
              message={t('events.empty')}
              resetLabel={t('events.reset')}
            />
          )
        ) : (
          /* Calendar View */
          <div className="animate-fade-in">
            {/* Calendar Navigation */}
            <div className="flex justify-between items-center mb-6 bg-mat-800 p-4 border border-mat-700">
              <button onClick={prevMonth} className="p-2 hover:bg-mat-700 text-white transition-colors" aria-label="Previous Month">
                <ChevronLeft className="w-5 h-5" />
              </button>
              <h2 className="text-2xl font-black text-white uppercase tracking-wider">
                {monthName} <span className="text-mat-500">{year}</span>
              </h2>
              <button onClick={nextMonth} className="p-2 hover:bg-mat-700 text-white transition-colors" aria-label="Next Month">
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>

            {/* Calendar Grid */}
            <div className="grid grid-cols-7 gap-px bg-mat-700 border border-mat-700 shadow-2xl">
              {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => (
                <div key={day} className="bg-mat-900 p-3 text-center text-xs font-bold uppercase tracking-widest text-gray-500">
                  {day}
                </div>
              ))}

              {/* Empty Cells */}
              {emptyDays.map(i => (
                <div key={`empty-${i}`} className="bg-mat-800/50 min-h-[120px]"></div>
              ))}

              {/* Day Cells */}
              {days.map(day => {
                const dayEvents = getEventsForDay(day);
                const isToday = new Date().getDate() === day && 
                                new Date().getMonth() === currentDate.getMonth() && 
                                new Date().getFullYear() === currentDate.getFullYear();

                return (
                  <div key={day} className={`bg-mat-800 min-h-[120px] p-2 border border-mat-700/50 hover:bg-mat-700/50 transition-colors relative group`}>
                    <div className={`text-sm font-bold mb-2 ${isToday ? 'bg-mat-500 text-white w-6 h-6 flex items-center justify-center rounded-full' : 'text-gray-400'}`}>
                      {day}
                    </div>

                    <div className="space-y-1">
                      {dayEvents.map(event => (
                        <div key={event.id} className="bg-mat-900 border-l-2 border-mat-500 p-1.5 cursor-pointer hover:bg-mat-700 transition-colors group/event">
                          <p className="text-[10px] font-bold text-white truncate leading-tight uppercase">{event.title}</p>
                          <p className="text-[9px] text-gray-500 flex items-center gap-1 mt-0.5">
                             <Clock className="w-2 h-2" /> {event.time}
                          </p>

                          {/* Tooltip for desktop */}
                          <div className="hidden md:block absolute z-20 bottom-full left-0 w-64 bg-mat-900 border border-mat-500 p-3 shadow-xl opacity-0 group-hover/event:opacity-100 pointer-events-none transition-opacity mb-2">
                            <h4 className="font-bold text-white text-sm mb-1">{event.title}</h4>
                            <div className="flex items-center gap-2 text-xs text-mat-500 mb-1">
                              <Clock className="w-3 h-3" /> {event.time}
