  // Calculator State
  const [privateForm, setPrivateForm] = useState({
    name: '', 
    email: '', 
    date: new Date().toISOString().split('T')[0],
    duration: 4, 
    guests: 40, 
    ticketsPerGuest: 2
  });

  // Quote State
  const [quote, setQuote] = useState({
    rentalBase: 0,
    consumableRevenue: 0,
    discount: 0,
    finalTotal: 0,
    pricePerPerson: 0,
    totalDrinks: 0,
    isWeekend: false,
    drinkPrice: 9.50
  });

  // Calculation Logic
  useEffect(() => {
    const calculateQuote = () => {
      const day = new Date(privateForm.date).getDay();
      const isWeekend = day === 5 || day === 6; // Friday or Saturday
      const DRINK_PRICE = 9.50; 

      // Commercial Rates: Weekday €80/h, Weekend €140/h
      const hourlyRate = isWeekend ? 140 : 80;
      const baseRental = privateForm.duration * hourlyRate;

      const totalDrinks = privateForm.guests * privateForm.ticketsPerGuest;
      const drinksRevenue = totalDrinks * DRINK_PRICE;

      // Rental Reduction Logic: 40% of the drinks revenue is deducted from the venue rental fee
      const reductionFactor = 0.40;
      const rentalDiscount = Math.min(baseRental, drinksRevenue * reductionFactor);

      const totalEstimated = (baseRental - rentalDiscount) + drinksRevenue;

      setQuote({
        rentalBase: baseRental,
        consumableRevenue: drinksRevenue,
        discount: rentalDiscount,
        finalTotal: totalEstimated,
        pricePerPerson: totalEstimated / privateForm.guests,
        totalDrinks,
        isWeekend,
        drinkPrice: DRINK_PRICE
      });
    };
    calculateQuote();
