import { MessageSquare, X, Send, Disc, Loader2 } from 'lucide-react';
import { sendMessageToGemini } from '../services/geminiService';
import { ChatMessage } from '../types';
import { useLanguage } from '../context/LanguageContext';

export const AIChat: React.FC = () => {
  const { t, language } = useLanguage();
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Initialize welcome message when language changes or on first load
  useEffect(() => {
    setMessages([
      { role: 'model', text: t('chat.welcome') }
    ]);
  }, [language, t]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = { role: 'user' as const, text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const response = await sendMessageToGemini(userMsg.text, language);

    setMessages(prev => [...prev, { role: 'model', text: response.text }]);
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSend();
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end font-sans">
      {/* Chat Window */}
      {isOpen && (
        <div className="mb-4 w-80 md:w-[450px] h-[600px] bg-mat-800 border border-mat-700 shadow-2xl flex flex-col overflow-hidden animate-fade-in rounded-t-lg">
          <div className="bg-mat-900 p-4 border-b-2 border-mat-500 flex justify-between items-center">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-mat-800 border border-mat-700 flex items-center justify-center rounded-full">
                <Disc className={`w-6 h-6 text-mat-500 ${isLoading ? 'animate-spin' : ''}`} />
              </div>
              <div>
                 <h3 className="font-bold text-mat-cream uppercase tracking-wider text-sm">{t('chat.staff')}</h3>
                 <span className="text-xs text-mat-500 flex items-center gap-1">● {t('chat.online')}</span>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-gray-500 hover:text-mat-cream transition-colors">
              <X className="w-5 h-5" />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-[#1f1c1a]">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[90%] p-4 text-sm leading-relaxed ${
                  msg.role === 'user' 
                    ? 'bg-mat-500 text-white rounded-l-xl rounded-tr-xl shadow-lg' 
                    : 'bg-mat-800 text-gray-200 border border-mat-700 rounded-r-xl rounded-tl-xl shadow-xl'
                }`}>
                  <div className="whitespace-pre-wrap">{msg.text}</div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-mat-800 border border-mat-700 p-4 rounded-r-xl rounded-tl-xl">
                  <Loader2 className="w-5 h-5 animate-spin text-mat-500" />
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          <div className="p-4 bg-mat-900 border-t border-mat-800 flex items-center space-x-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder={t('chat.placeholder')}
              className="flex-1 bg-mat-800 text-mat-cream text-sm px-4 py-4 focus:outline-none border border-mat-700 focus:border-mat-500 transition-colors placeholder-gray-600 rounded-lg"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="p-4 bg-mat-500 hover:bg-mat-400 text-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors rounded-lg shadow-lg"
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      {/* Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="w-16 h-16 bg-mat-500 text-white rounded-full shadow-2xl flex items-center justify-center hover:bg-mat-400 transition-all hover:scale-110 border-4 border-mat-900 group"
        aria-label="Open Assistant"
      >
        {isOpen ? <X className="w-6 h-6" /> : <MessageSquare className="w-6 h-6 group-hover:animate-bounce" />}
      </button>
    </div>
  );
};

