import React, { useState } from 'react';
import { Calendar, Clock, MapPin, Check, Ticket, ListMusic, Handshake } from 'lucide-react';
import { Event } from '../types';
import { toggleRsvp } from '../services/geminiService';
import { useLanguage } from '../context/LanguageContext';

interface EventCardProps {
  event: Event;
}

export const EventCard: React.FC<EventCardProps> = ({ event }) => {
  const { t } = useLanguage();
  const [isAttending, setIsAttending] = useState(false);
  const [attendeeCount, setAttendeeCount] = useState(event.attendees);

  const isFree = event.price === 0;
  const isPromoterRequest = event.category === 'Promoter Request';

  const handleRsvp = () => {
    if (isFree) {
      const newStatus = !isAttending;
      setIsAttending(newStatus);
      setAttendeeCount(prev => newStatus ? prev + 1 : prev - 1);
      toggleRsvp(event.title, newStatus);
    } else if (event.ticketLink) {
      window.open(event.ticketLink, '_blank');
    }
  };

  return (
    <article className={`
      bg-mat-800 
      border-2 ${isAttending && isFree ? 'border-mat-accent shadow-mat-accent/10' : isPromoterRequest ? 'border-purple-500/50 shadow-purple-500/10' : 'border-mat-700'} 
      shadow-xl 
      hover:shadow-mat-500/20 hover:-translate-y-1.5 hover:scale-[1.02] hover:border-mat-500
      transition-all duration-500 ease-out
      flex flex-col md:flex-row 
      overflow-hidden group relative 
      w-full
    `}>

      {/* Badges Overlay */}
      <div className="absolute top-4 right-4 z-20 flex flex-col gap-2 items-end">
        {isAttending && isFree && (
          <div className="bg-mat-accent text-mat-900 px-4 py-1.5 font-black uppercase text-[9px] tracking-[0.2em] shadow-xl flex items-center gap-2 animate-fade-in">
            <Check className="w-3 h-3" /> {t('events.card.onthelist')}
          </div>
        )}
        <div className={`px-4 py-1.5 font-black uppercase text-[9px] tracking-[0.2em] shadow-xl border-2 ${isFree ? 'bg-green-600 border-green-400' : 'bg-mat-500 border-mat-400'}`}>
          {isFree ? t('events.card.free') : `€${event.price}`}
        </div>
      </div>

      {/* Image Container - Rock solid 16:9 Aspect Ratio on mobile, fixed width on desktop */}
      <div className="md:w-[40%] xl:w-[35%] relative overflow-hidden bg-mat-900 flex-shrink-0">
        <div className="aspect-[16/9] md:aspect-auto md:h-full w-full">
          <img 
            src={event.imageUrl} 
            alt={event.title} 
            className="w-full h-full object-cover transition-all duration-[1500ms] grayscale group-hover:grayscale-0 scale-100 group-hover:scale-110"
          />
        </div>
        <div className={`absolute bottom-0 left-0 ${isPromoterRequest ? 'bg-purple-900/95 text-purple-200 border-purple-500/50' : 'bg-mat-900/95 text-mat-500 border-mat-700'} text-[9px] font-black px-5 py-2.5 uppercase tracking-[0.3em] border-t border-r backdrop-blur-sm transition-colors`}>
          {isPromoterRequest && <Handshake className="w-3 h-3 inline-block mr-2 -mt-0.5" />}
          {event.category}
        </div>
      </div>

      {/* Content Container */}
      <div className="p-8 md:p-10 flex flex-col justify-between flex-1">
        <div>
          <div className="flex items-center text-mat-500 font-black text-[9px] uppercase tracking-[0.4em] mb-4">
            <Calendar className="w-3 h-3 mr-2" />
            {event.date}
          </div>

          <h3 className={`text-2xl md:text-3xl xl:text-4xl font-black text-mat-cream uppercase leading-[1] mb-5 group-hover:text-mat-500 transition-colors tracking-tighter ${isPromoterRequest ? 'italic' : ''}`}>
            {event.title}
          </h3>

          <p className="text-gray-400 text-sm leading-relaxed border-l-2 border-mat-700/50 pl-6 mb-8 line-clamp-2 md:line-clamp-3 font-medium">
            {event.description}
          </p>
        </div>

        {/* Actions & Info Footer */}
        <div className="pt-6 border-t border-mat-700/40 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
          <div className="flex flex-col gap-2 text-[9px] text-gray-500 font-black uppercase tracking-[0.2em]">
            <div className="flex items-center group/info">
              <Clock className="w-4 h-4 mr-3 text-mat-700 group-hover/info:text-mat-500 transition-colors" />
              {event.time}
            </div>
            <div className="flex items-center group/info">
              <MapPin className="w-4 h-4 mr-3 text-mat-700 group-hover/info:text-mat-500 transition-colors" />
              {event.location}
            </div>
            <div className={`mt-1 flex items-center gap-2 ${isPromoterRequest ? 'text-purple-400' : 'text-mat-500'}`}>
               <span className={`w-1.5 h-1.5 ${isPromoterRequest ? 'bg-purple-500' : 'bg-mat-500'} rounded-full animate-pulse`}></span>
               {attendeeCount} {isFree ? t('events.card.attending') : t('events.card.sold')}
            </div>
          </div>

          <button 
            onClick={handleRsvp}
            className={`
              px-8 py-4 
              font-black uppercase text-[10px] tracking-[0.2em] 
              flex items-center justify-center gap-3 
              transition-all duration-300 
              border-2 clip-path-slant
              shadow-lg
              hover:-translate-y-1 hover:shadow-mat-500/30
              ${
                isFree 
                  ? isAttending
                    ? 'bg-mat-accent border-mat-accent text-mat-900' 
                    : isPromoterRequest 
                      ? 'bg-purple-600 border-purple-500 text-white hover:bg-purple-500'
                      : 'bg-transparent border-mat-500 text-mat-500 hover:bg-mat-500 hover:text-white'
                  : 'bg-mat-500 border-mat-500 text-white hover:bg-mat-400 hover:border-mat-400'
              }
            `}
          >
            {isFree ? (
              isAttending ? <Check className="w-5 h-5" /> : isPromoterRequest ? <Handshake className="w-5 h-5" /> : <ListMusic className="w-5 h-5" />
            ) : (
              <Ticket className="w-5 h-5" />
            )}
            {isFree 
              ? isAttending 
                ? t('events.card.onthelist') 
                : isPromoterRequest 
                  ? t('events.filter.promoter_request') 
                  : t('events.card.guestlist') 
              : t('events.card.get_tickets')}
          </button>
        </div>
      </div>
    </article>
  );
};

import React, { useState, useMemo } from 'react';
import { Search, Filter, Calendar as CalendarIcon, LayoutGrid, ChevronLeft, ChevronRight, Clock, Mic2, Music2, Speaker, Settings, ArrowRight, Zap, Disc, Sliders, ExternalLink, Send, CheckCircle } from 'lucide-react';
import { EventCard } from '../components/EventCard';
import { SEO } from '../components/SEO';
import { MOCK_EVENTS } from '../constants';
import { useLanguage } from '../context/LanguageContext';
import { Link } from 'react-router-dom';

export const Events: React.FC = () => {
  const { t } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [viewMode, setViewMode] = useState<'list' | 'calendar'>('list');
  const [showInquiryForm, setShowInquiryForm] = useState(false);
  const [inquiryStatus, setInquiryStatus] = useState<'idle' | 'sending' | 'success'>('idle');

  // Set current date to today for accurate filtering and display
  const [currentDate, setCurrentDate] = useState(new Date());

  const categories = ['All', 'Disco', 'House', 'Live', 'Social', 'Promoter Request'];

  const filteredEvents = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];

    return MOCK_EVENTS.filter(event => {
      // Logic: Only show events from today onwards
      const isFutureOrToday = event.date >= todayStr;
      if (!isFutureOrToday) return false;

      const matchesSearch = event.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            event.description.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = selectedCategory === 'All' || event.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchTerm, selectedCategory]);

  // Calendar Logic
  const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay();

  const startingDayIndex = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const getEventsForDay = (day: number) => {
    const year = currentDate.getFullYear();
    const month = String(currentDate.getMonth() + 1).padStart(2, '0');
    const dateString = `${year}-${month}-${String(day).padStart(2, '0')}`;
    return filteredEvents.filter(e => e.date === dateString);
  };

  const monthName = currentDate.toLocaleString('default', { month: 'long' });
  const year = currentDate.getFullYear();

  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const emptyDays = Array.from({ length: startingDayIndex }, (_, i) => i);

  const getCategoryDisplay = (cat: string) => {
    if (cat === 'All') return t('events.filter.all');
    if (cat === 'Promoter Request') return t('events.filter.promoter_request');
    return cat;
  };

  const handleInquirySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setInquiryStatus('sending');
    setTimeout(() => {
      setInquiryStatus('success');
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-mat-900 text-mat-cream">
      <SEO titleKey="seo.events.title" descriptionKey="seo.events.description" />

      {/* Hero Header */}
