                 </div>
               ) : (
                 <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="flex items-center gap-3 mb-8">
                       <Mail className="w-6 h-6 text-mat-500" />
                       <h4 className="text-xl font-black text-white uppercase tracking-tighter">{t('private.booking_details')}</h4>
                    </div>

                    <div className="space-y-5">
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-mat-500 uppercase tracking-widest">{t('private.form.label.date')}</label>
                          <input required name="date" type="date" value={formData.date} onChange={handleInputChange} className="w-full bg-mat-900 border border-mat-700 p-4 text-white focus:border-mat-500 outline-none uppercase text-xs font-black" />
                       </div>

                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-mat-500 uppercase tracking-widest">{t('private.form.label.name')}</label>
                          <input required name="name" type="text" value={formData.name} onChange={handleInputChange} className="w-full bg-mat-900 border border-mat-700 p-4 text-white focus:border-mat-500 outline-none uppercase text-xs font-black" />
                       </div>

                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-mat-500 uppercase tracking-widest">{t('private.form.label.email')}</label>
                          <input required name="email" type="email" value={formData.email} onChange={handleInputChange} className="w-full bg-mat-900 border border-mat-700 p-4 text-white focus:border-mat-500 outline-none uppercase text-xs font-black" />
                       </div>

                       {eventType === 'promoter' && (
                         <div className="space-y-5 animate-fade-in">
                            <div className="space-y-2">
                               <label className="text-[10px] font-black text-mat-500 uppercase tracking-widest">{t('private.form.company')}</label>
                               <input name="companyName" type="text" value={formData.companyName} onChange={handleInputChange} className="w-full bg-mat-900 border border-mat-700 p-4 text-white focus:border-mat-500 outline-none uppercase text-xs font-black" />
                            </div>
                            <div className="space-y-2">
                               <label className="text-[10px] font-black text-mat-500 uppercase tracking-widest">{t('private.form.attendance')}</label>
                               <select name="attendance" value={formData.attendance} onChange={handleInputChange} className="w-full bg-mat-900 border border-mat-700 p-4 text-white focus:border-mat-500 outline-none uppercase text-xs font-black appearance-none">
                                  <option value="">Select Range</option>
                                  <option value="40-60">40 - 60 PAX</option>
                                  <option value="60-80">60 - 80 PAX</option>
                                  <option value="80-100">80 - 100 PAX</option>
                               </select>
                            </div>
                         </div>
                       )}
                    </div>

                    <button 
                      type="submit" 
                      disabled={isProcessing}
                      className="w-full py-6 bg-mat-500 hover:bg-mat-400 text-white font-black uppercase tracking-[0.2em] text-xs transition-all shadow-xl hover:-translate-y-1 flex items-center justify-center gap-3 clip-path-slant"
                    >
                       {isProcessing ? (
                         <Loader2 className="w-5 h-5 animate-spin" />
                       ) : (
                         <ArrowRight className="w-5 h-5" />
                       )}
                       {isProcessing ? 'Processing' : t('private.btn.request')}
                    </button>

                    <p className="text-[9px] text-gray-600 text-center uppercase tracking-widest leading-relaxed">
                       {t('private.disclaimer')}
                    </p>
                 </form>
               )}
            </div>

            {/* Support Protocol */}
            <div className="mt-8 p-6 border-l-2 border-mat-700 flex items-start gap-4">
               <Shield className="w-5 h-5 text-gray-700 mt-1" />
               <div>
                  <h5 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-1">{t('private.form.protocol.label')}</h5>
                  <p className="text-[10px] text-gray-600 font-medium">
                     {t('private.form.protocol.desc')}
                  </p>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export interface Event {
  id: string;
  title: string;
  date: string;
  time: string;
  location: string;
  description: string;
  category: 'Disco' | 'House' | 'Live' | 'Social' | 'Promoter Request';
  imageUrl: string;
  attendees: number;
  price: number;
  ticketLink?: string;
}

export interface Post {
  id: string;
  author: string;
  avatar: string;
  content: string;
  likes: number;
  comments: number;
  timestamp: string;
  tags: string[];
}

