  role: 'user' | 'model';
  text: string;
}

export interface VinylRecord {
  id: string;
  artist: string;
  title: string;
  label: string;
  year: string;
  condition: 'Mint' | 'NM' | 'VG+' | 'VG';
  price: number;
  coverUrl: string;
  genre: 'Disco' | 'House' | 'Funk' | 'Jazz' | 'Ambient';
  format: 'LP' | '12"' | '7"';
