                           <h4 className="text-white font-black uppercase text-xs tracking-widest mb-2">Long-term Residency</h4>
                           <p className="text-gray-500 text-xs leading-relaxed">We prioritize recurring collaborations to build deep community connections through monthly residencies.</p>
                        </div>
                     </div>
                  </div>

                  {/* Form Toggle Trigger */}
                  {!showInquiryForm ? (
                    <div className="pt-10">
                       <button 
                         onClick={() => setShowInquiryForm(true)}
