                       >
                          PROPOSE YOUR PERFORMANCE <ArrowRight className="w-7 h-7 group-hover/btn:translate-x-3 transition-transform" />
                       </button>
                    </div>
                  ) : (
                    <div className="pt-8 animate-fade-in bg-mat-900/50 p-12 border border-mat-700 rounded-[2.5rem] backdrop-blur-md shadow-2xl">
                       {inquiryStatus === 'success' ? (
                         <div className="text-center py-16">
                            <div className="w-24 h-24 bg-mat-800 rounded-full flex items-center justify-center mx-auto mb-8 border border-mat-500 shadow-xl">
                               <CheckCircle className="w-12 h-12 text-mat-500" />
                            </div>
                            <h4 className="text-3xl font-black text-white uppercase tracking-tighter mb-6 font-exo">Protocolo Recibido</h4>
