                            <button onClick={() => {setShowInquiryForm(false); setInquiryStatus('idle');}} className="text-mat-500 font-black uppercase text-[10px] tracking-[0.4em] underline decoration-2 underline-offset-8 hover:text-white transition-colors">Volver al Portal</button>
                         </div>
                       ) : (
                         <form onSubmit={handleInquirySubmit} className="space-y-10">
                            <div className="grid md:grid-cols-2 gap-10">
                               <div className="space-y-4">
                                  <label className="block text-[10px] font-black text-mat-500 uppercase tracking-[0.4em]">ARTIST / COLLECTIVE NAME</label>
                                  <input required type="text" className="w-full bg-mat-900 border border-mat-700 text-white p-5 focus:border-mat-500 outline-none transition-all uppercase text-xs font-black tracking-widest rounded-lg" placeholder="NAME" />
                               </div>
                               <div className="space-y-4">
                                  <label className="block text-[10px] font-black text-mat-500 uppercase tracking-[0.4em]">SONIC MODALITY</label>
                                  <select className="w-full bg-mat-900 border border-mat-700 text-white p-5 focus:border-mat-500 outline-none transition-all uppercase text-xs font-black tracking-widest appearance-none rounded-lg">
                                     <option>ACOUSTIC SET</option>
                                     <option>LIVE ELECTRONIC</option>
                                     <option>EXPERIMENTAL AMBIENT</option>
                                     <option>JAZZ / AVANT-GARDE</option>
                                  </select>
                               </div>
                            </div>

                            <div className="space-y-4">
                               <label className="block text-[10px] font-black text-mat-500 uppercase tracking-[0.4em]">PORTFOLIO / LIVE LINKS</label>
                               <div className="flex bg-mat-900 border border-mat-700 focus-within:border-mat-500 transition-all rounded-lg overflow-hidden">
                                  <div className="p-5 bg-mat-800 text-gray-500 border-r border-mat-700"><ExternalLink className="w-6 h-6" /></div>
                                  <input required type="url" placeholder="YOUTUBE / SOUNDCLOUD / PORTFOLIO URL" className="flex-1 bg-transparent text-white p-5 outline-none uppercase text-xs font-black tracking-widest" />
                               </div>
                            </div>

                            <div className="space-y-4">
                               <label className="block text-[10px] font-black text-mat-500 uppercase tracking-[0.4em]">TECHNICAL RIDER SUMMARY</label>
                               <textarea required placeholder="INPUT LIST, POWER NEEDS, ANALOG MIXER PREFERENCE..." className="w-full bg-mat-900 border border-mat-700 text-white p-5 focus:border-mat-500 outline-none transition-all h-36 uppercase text-xs font-black tracking-widest resize-none rounded-lg leading-relaxed" />
                            </div>

                            <button 
                              type="submit" 
                              disabled={inquiryStatus === 'sending'}
                              className="w-full py-7 bg-white text-mat-900 font-black uppercase tracking-[0.3em] text-sm transition-all shadow-2xl hover:bg-mat-500 hover:text-white flex items-center justify-center gap-5 clip-path-slant"
                            >
                               {inquiryStatus === 'sending' ? 'ENVIANDO PROTOCOLO...' : <><Send className="w-6 h-6" /> SUBMIT PROTOCOL</>}
                            </button>
                         </form>
                       )}
                    </div>
                  )}
               </div>

               {/* Right Technical Protocol Column */}
               <div className="lg:col-span-5 flex flex-col relative overflow-hidden bg-mat-900/40">
                  {/* Background Decoration */}
