                     <img 
                       src="https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?q=80&w=1200&auto=format&fit=crop" 
                       className="w-full h-full object-cover opacity-20 grayscale scale-110" 
                       alt="Technical Gear" 
                     />
                     <div className="absolute inset-0 bg-gradient-to-l from-mat-800 via-mat-800/90 to-transparent"></div>
                  </div>

                  {/* Signal Flow Protocol Card */}
                  <div className="flex-1 p-12 lg:p-20 relative z-10 flex flex-col justify-center">
                     <div className="bg-mat-900 border-2 border-mat-500/40 p-12 space-y-12 shadow-[0_40px_80px_rgba(0,0,0,0.6)] transform lg:rotate-3 hover:rotate-0 transition-transform duration-1000 group/protocol backdrop-blur-xl">
                        <div className="flex justify-between items-start border-b border-mat-700 pb-8">
                           <div className="space-y-3">
                              <div className="flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-mat-500 animate-pulse"></span>
                                <h3 className="text-[10px] font-black text-mat-500 uppercase tracking-[0.6em] mb-1">FIDELITY PROTOCOL</h3>
                              </div>
                              <p className="text-white text-3xl font-black uppercase font-exo tracking-tighter leading-none">The Signal Path</p>
                           </div>
                           <Settings className="w-10 h-10 text-mat-700 animate-spin-slow group-hover/protocol:text-mat-500 transition-colors" />
                        </div>

                        <div className="space-y-8">
                           <div className="flex items-center gap-6 border-b border-mat-700/50 pb-6 group/item">
                              <div className="p-3 bg-mat-800 border border-mat-700 rounded-lg group-hover/item:border-mat-500 transition-colors">
                                 <Speaker className="w-6 h-6 text-mat-500" />
                              </div>
                              <div className="flex-1">
                                 <p className="text-[9px] font-black text-gray-500 uppercase tracking-[0.3em] mb-1">MONITORING</p>
                                 <p className="text-sm font-black text-mat-cream uppercase tracking-widest font-exo">VOID ACOUSTICS AIRSTREAM</p>
                              </div>
                           </div>
                           <div className="flex items-center gap-6 border-b border-mat-700/50 pb-6 group/item">
                              <div className="p-3 bg-mat-800 border border-mat-700 rounded-lg group-hover/item:border-mat-500 transition-colors">
                                 <Sliders className="w-6 h-6 text-mat-500" />
                              </div>
                              <div className="flex-1">
                                 <p className="text-[9px] font-black text-gray-500 uppercase tracking-[0.3em] mb-1">ANALOG DESK</p>
                                 <p className="text-sm font-black text-mat-cream uppercase tracking-widest font-exo">ALLEN & HEATH XONE:96</p>
                              </div>
                           </div>
                           <div className="flex items-center gap-6 border-b border-mat-700/50 pb-6 group/item">
                              <div className="p-3 bg-mat-800 border border-mat-700 rounded-lg group-hover/item:border-mat-500 transition-colors">
                                 <Disc className="w-6 h-6 text-mat-500" />
                              </div>
                              <div className="flex-1">
                                 <p className="text-[9px] font-black text-gray-500 uppercase tracking-[0.3em] mb-1">PLAYBACK</p>
                                 <p className="text-sm font-black text-mat-cream uppercase tracking-widest font-exo">TECHNICS 1210 MK7 (DUAL)</p>
                              </div>
                           </div>
                           <div className="flex items-center gap-6 group/item">
                              <div className="p-3 bg-mat-800 border border-mat-700 rounded-lg group-hover/item:border-mat-500 transition-colors">
                                 <Volume2 className="w-6 h-6 text-mat-500" />
                              </div>
                              <div className="flex-1">
                                 <p className="text-[9px] font-black text-gray-500 uppercase tracking-[0.3em] mb-1">FRONT OF HOUSE</p>
                                 <p className="text-sm font-black text-mat-cream uppercase tracking-widest font-exo">HIGH-FIDELITY POINT SOURCE</p>
                              </div>
                           </div>
                        </div>

                        <div className="pt-4">
                           <div className="flex items-center gap-4 px-6 py-4 bg-mat-800 border border-mat-700 rounded-xl">
                              <div className="w-3 h-3 rounded-full bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.6)]"></div>
                              <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em]">OPTIMIZED FOR NUANCE</span>
                           </div>
                        </div>
                     </div>
                  </div>
               </div>
            </div>
          </div>

          {/* Background Glow Effect */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[90%] h-[90%] bg-mat-500/5 blur-[150px] pointer-events-none -z-0"></div>
        </section>
      </div>
    </div>
  );
};

const EmptyState: React.FC<{ reset: () => void, message: string, resetLabel: string }> = ({ reset, message, resetLabel }) => (
  <div className="text-center py-40 border-4 border-dashed border-mat-800 rounded-[3rem] bg-mat-800/20">
    <Disc className="w-20 h-20 text-mat-800 mx-auto mb-8 animate-pulse" />
    <h3 className="text-3xl font-black text-gray-700 uppercase mb-6 tracking-tighter">No sessions found</h3>
    <p className="text-gray-500 mb-10 font-medium text-lg italic">{message}</p>
    <button 
      onClick={reset}
      className="px-12 py-4 bg-mat-900 border-2 border-mat-700 text-mat-500 font-black uppercase tracking-widest text-[11px] hover:bg-mat-500 hover:text-white transition-all rounded-xl"
    >
      {resetLabel}
    </button>
  </div>
);
